/*
 * NKSE service worker — generated by toolchain_foundry/compiler.esbuild.mjs.
 * Do not edit dist/sw.js by hand: it is rebuilt from this template.
 *
 * Caching is deliberately not uniform. Stale UI or stale schedule is worse than
 * a slow first paint, so the rules split by what the file is:
 *
 *   index.html, schedule.json   network-first  — always the freshest copy
 *   *.hhhhhhhh.js/.css          cache-first    — content hash means immutable
 *   images, icons, manifest     cache-first    — background refresh
 *   everything else             network-first  — cache only as offline fallback
 */

const VERSION = '__VERSION__';
const CACHE = `${VERSION}-shell`;
const DATA_CACHE = `${VERSION}-data`;
const IMMUTABLE = /\.[0-9a-f]{8}\.(?:js|css)$/;

const PRECACHE = __PRECACHE__;

// Пути оболочки для быстрого поиска. Подприложения сюда не входят.
const PRECACHE_PATHS = new Set(
    PRECACHE.map((p) => new URL(p, self.location).pathname)
);

const DATA_ASSETS = ['schedule.json'];

// No third-party origins left: fonts are self-hosted, so nothing external must
// be warmed up on install.
const VENDOR_ASSETS = [];

self.addEventListener('install', (event) => {
    event.waitUntil(
        caches
            .open(CACHE)
            .then((cache) => cache.addAll(PRECACHE).catch(() => {}))
            .then(() =>
                caches.open(CACHE).then((cache) =>
                    Promise.all(VENDOR_ASSETS.map((u) => cache.add(u).catch(() => {})))
                )
            )
            .then(() =>
                caches.open(DATA_CACHE).then((cache) =>
                    Promise.all(DATA_ASSETS.map((u) => cache.add(u).catch(() => {})))
                )
            )
            .then(() => self.skipWaiting())
    );
});

self.addEventListener('activate', (event) => {
    event.waitUntil(
        caches
            .keys()
            .then((keys) => Promise.all(keys.filter((k) => !k.startsWith(VERSION)).map((k) => caches.delete(k))))
            .then(() => self.clients.claim())
    );
});

async function networkFirst(req, cacheName, fallbackUrl) {
    try {
        const res = await fetch(req);
        if (res && (res.ok || res.type === 'opaque')) {
            const cache = await caches.open(cacheName);
            cache.put(req, res.clone());
        }
        return res;
    } catch (err) {
        const cache = await caches.open(cacheName);
        const hit = await cache.match(req, { ignoreSearch: true });
        if (hit) return hit;
        if (fallbackUrl) {
            const shell = await caches.open(CACHE);
            const page = await shell.match(fallbackUrl);
            if (page) return page;
        }
        return Response.error();
    }
}

async function cacheFirst(req, cacheName) {
    const cache = await caches.open(cacheName);
    const hit = await cache.match(req);
    if (hit) {
        // Refresh in the background; the hash guarantees the payload is the same.
        fetch(req)
            .then((res) => res && res.ok && cache.put(req, res.clone()))
            .catch(() => {});
        return hit;
    }
    const res = await fetch(req);
    if (res && res.ok) cache.put(req, res.clone());
    return res;
}

self.addEventListener('fetch', (event) => {
    const req = event.request;
    if (req.method !== 'GET') return;

    const url = new URL(req.url);

    if (url.origin === self.location.origin && url.pathname.endsWith('schedule.json')) {
        event.respondWith(
            fetch(req)
                .then((res) => {
                    if (res && res.ok) {
                        const copy = res.clone();
                        caches.open(DATA_CACHE).then((c) => c.put(req, copy));
                    }
                    return res;
                })
                .catch(() =>
                    caches.match(req, { ignoreSearch: true }).then((hit) => {
                        if (hit) hit.headers.set('X-NKSE-Cache', 'offline');
                        return hit;
                    })
                )
        );
        return;
    }

    /* The messenger is updated independently of the schedule bundles. Never
       serve a stale app.js/config.js from the shell cache. */
    if (url.origin === self.location.origin && url.pathname.includes('/messenger/')) {
        event.respondWith(networkFirst(req, CACHE));
        return;
    }

    if (req.mode === 'navigate') {
        event.respondWith(networkFirst(req, CACHE, 'index.html'));
        return;
    }

    if (url.origin === self.location.origin && IMMUTABLE.test(url.pathname)) {
        event.respondWith(cacheFirst(req, CACHE));
        return;
    }

    // Только файлы оболочки. Подприложения (/library/, /wishes/, /messenger/)
    // намеренно НЕ кэшируются: иначе после деплоя люди получают старый app.js
    // и старые API-адреса, пока service worker не обновится.
    const isShell =
        url.origin === self.location.origin &&
        PRECACHE_PATHS.has(url.pathname);

    if (!isShell) return;
    event.respondWith(cacheFirst(req, CACHE));
});

self.addEventListener('message', (event) => {
    if (event.data === 'SKIP_WAITING') self.skipWaiting();
    if (event.data === 'CLEAR_CACHES') {
        event.waitUntil(caches.keys().then((keys) => Promise.all(keys.map((k) => caches.delete(k)))));
    }
});
